<?php require_once 'config.php';$users=[['admin','admin123','Admin','System Administrator'],['doctor','doctor123','Doctor','Dr. Primary Consultant'],['reception','reception123','Reception','Front Desk Executive']];foreach($users as $u){$s=$conn->prepare('SELECT id FROM users WHERE username=?');$s->bind_param('s',$u[0]);$s->execute();$exists=$s->get_result()->num_rows;$s->close();if(!$exists){$h=password_hash($u[1],PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(username,password_hash,role,full_name) VALUES(?,?,?,?)');$s->bind_param('ssss',$u[0],$h,$u[2],$u[3]);$s->execute();$s->close();echo 'Created '.htmlspecialchars($u[0])."<br>"; }else echo htmlspecialchars($u[0])." already exists.<br>";}echo '<br>Delete install_admin.php now.';
